mapper.select:
SELECT



    AND a.status = #{q.status}




                AND MATCH(a.title, a.summary) AGAINST (#{q.keyword} IN BOOLEAN MODE)


                AND (a.title LIKE CONCAT('%', #{q.keyword}, '%')
                  OR a.summary LIKE CONCAT('%', #{q.keyword}, '%'))



    AND a.category_id = #{q.categoryId}

        AND EXISTS (SELECT 1 FROM article_tag at2 WHERE at2.article_id = a.id AND at2.tag_id = #{q.tagId})


        AND DATE_FORMAT(a.publish_time, '%Y-%m') = #{q.yearMonth}


ORDER BY a.is_top DESC, a.publish_time DESC
